args.sparql:
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?alanBD ?ashleyBD ?younger ?youngerLabel WHERE {
  OPTIONAL { dbr:Alan_Morrissey dbo:birthDate ?bdAlan . }
  OPTIONAL { dbr:Alan_Morrissey dbp:born ?bdAlan2 . }
  BIND(coalesce(?bdAlan, ?bdAlan2) AS ?alanBD)

  OPTIONAL { dbr:Ashley_Hoffman dbo:birthDate ?bdAshley . }
  OPTIONAL { dbr:Ashley_Hoffman dbp:born ?bdAshley2 . }
  BIND(coalesce(?bdAshley, ?bdAshley2) AS ?ashleyBD)

  FILTER(bound(?alanBD) && bound(?ashleyBD))

  BIND(IF(?alanBD > ?ashleyBD, dbr:Alan_Morrissey, dbr:Ashley_Hoffman) AS ?younger)
  OPTIONAL { ?younger rdfs:label ?youngerLabel . FILTER(lang(?youngerLabel) = "en") }
}

